var _0011_guide_niche_default = "-- Guide outfit niche, and a charge unit so a price can be per person or per boat.\r\n-- Existing menus get the section labels a customer would expect for that trade.\r\n\r\nalter table services add column if not exists price_unit text not null default 'flat';\r\n\r\ndo $$\r\ndeclare r record;\r\nbegin\r\n  for r in\r\n    select conname from pg_constraint\r\n    where conrelid = 'shops'::regclass\r\n      and contype = 'c'\r\n      and pg_get_constraintdef(oid) ilike '%niche%'\r\n  loop\r\n    execute format('alter table shops drop constraint %I', r.conname);\r\n  end loop;\r\nend $$;\r\n\r\nalter table shops add constraint shops_niche_check\r\n  check (niche in ('location', 'field', 'studio', 'music', 'contractor', 'fitness', 'tattoo', 'guide'));\r\n\r\nalter table services drop constraint if exists services_price_unit_check;\r\nalter table services add constraint services_price_unit_check\r\n  check (price_unit in ('flat', 'person', 'boat'));\r\n\r\nupdate services set group_label = 'Booth', sort_order = 3 where id = 'svc_ll_feature';\r\nupdate services set group_label = 'Stage', sort_order = 4 where id = 'svc_ll_live';\r\nupdate services set group_label = 'Booth' where id = 'svc_ll_session';\r\n\r\nupdate services set group_label = 'Cut' where id in ('svc_sals_cut', 'svc_sals_fade');\r\nupdate services set group_label = 'Razor' where id in ('svc_sals_shave', 'svc_sals_beard');\r\n\r\nupdate services set group_label = 'At the curb' where id in ('svc_dg_diag', 'svc_dg_mobile');\r\nupdate services set group_label = 'In the bay' where id in ('svc_dg_oil', 'svc_dg_brakes');\r\n\r\nupdate services set group_label = 'Start' where id = 'svc_apps_disc';\r\nupdate services set group_label = 'Build' where id in ('svc_apps_launch', 'svc_apps_console', 'svc_apps_ring');\r\n";
var _0012_universal_niches_default = "-- More trades that book by time, plus a flag for a one-person shop.\r\n\r\nalter table shops add column if not exists works_alone boolean not null default false;\r\n\r\ndo $$\r\ndeclare r record;\r\nbegin\r\n  for r in\r\n    select conname from pg_constraint\r\n    where conrelid = 'shops'::regclass\r\n      and contype = 'c'\r\n      and pg_get_constraintdef(oid) ilike '%niche%'\r\n  loop\r\n    execute format('alter table shops drop constraint %I', r.conname);\r\n  end loop;\r\nend $$;\r\n\r\nalter table shops add constraint shops_niche_check\r\n  check (niche in (\r\n    'location', 'field', 'studio', 'music', 'contractor', 'fitness', 'tattoo', 'guide',\r\n    'salon', 'beauty', 'wellness', 'lessons', 'photo', 'pets', 'clean', 'practice',\r\n    'counsel', 'events', 'trade'\r\n  ));\r\n";
var _0013_booking_notices_default = "-- Employee station notices, guest contact email, and an accept confirmation kind.\r\n\r\nalter table appointments add column if not exists customer_email text not null default '';\r\n\r\nalter table shop_notifications add column if not exists employee_id text;\r\n\r\ndo $$\r\nbegin\r\n  alter table shop_notifications\r\n    add constraint shop_notifications_employee_fk\r\n    foreign key (employee_id) references employees(id) on delete cascade;\r\nexception\r\n  when duplicate_object then null;\r\nend $$;\r\n\r\ndo $$\r\ndeclare r record;\r\nbegin\r\n  for r in\r\n    select conname from pg_constraint\r\n    where conrelid = 'shop_notifications'::regclass\r\n      and contype = 'c'\r\n      and pg_get_constraintdef(oid) ilike '%kind%'\r\n  loop\r\n    execute format('alter table shop_notifications drop constraint %I', r.conname);\r\n  end loop;\r\nend $$;\r\n\r\nalter table shop_notifications drop constraint if exists shop_notifications_kind_check;\r\nalter table shop_notifications add constraint shop_notifications_kind_check\r\n  check (kind in ('booking_request', 'booking_paid', 'inquiry', 'booking_confirmed'));\r\n\r\ncreate index if not exists shop_notifications_employee_idx\r\n  on shop_notifications (employee_id, created_at desc);\r\n";
var _0014_master_funnel_default = "-- Preloaded businesses for regional funnels, and the visits those links produce.\r\n-- The app connection owns these tables. RLS is on with no public policy so a\r\n-- restricted role cannot read the lead list.\r\n\r\ncreate table if not exists preloaded_leads (\r\n  id             text primary key,\r\n  business_name  text not null,\r\n  trade_type     text not null,\r\n  city           text not null default '',\r\n  county         text not null default '',\r\n  lead_slug      text not null,\r\n  claimed        boolean not null default false,\r\n  shop_id        text references shops(id) on delete set null,\r\n  created_at     timestamptz not null default now()\r\n);\r\n\r\ncreate unique index if not exists preloaded_leads_slug_idx on preloaded_leads (lead_slug);\r\ncreate index if not exists preloaded_leads_county_idx on preloaded_leads (county);\r\n\r\ncreate table if not exists funnel_visits (\r\n  id           text primary key,\r\n  lead_slug    text not null default '',\r\n  utm_source   text not null default '',\r\n  county       text not null default '',\r\n  landed_path  text not null default '/',\r\n  shop_id      text references shops(id) on delete set null,\r\n  created_at   timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists funnel_visits_slug_idx on funnel_visits (lead_slug, created_at desc);\r\ncreate index if not exists funnel_visits_county_idx on funnel_visits (county, created_at desc);\r\n\r\nalter table preloaded_leads enable row level security;\r\nalter table funnel_visits enable row level security;\r\n";
var _0015_outreach_default = "-- Contact lines on preloaded businesses, and a log of simulated outreach batches.\r\n\r\nalter table preloaded_leads add column if not exists contact_email text not null default '';\r\nalter table preloaded_leads add column if not exists contact_phone text not null default '';\r\n\r\ncreate table if not exists outreach_campaigns (\r\n  id           text primary key,\r\n  county       text not null,\r\n  trade_type   text not null,\r\n  lead_count   integer not null,\r\n  status       text not null default 'simulated',\r\n  template     text not null default '',\r\n  created_at   timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists outreach_campaigns_created_idx\r\n  on outreach_campaigns (created_at desc);\r\n\r\nalter table outreach_campaigns enable row level security;\r\n";
var _0016_lead_public_default = "-- Public listing details the outreach hooks can quote.\r\n\r\nalter table preloaded_leads add column if not exists contact_name text not null default '';\r\nalter table preloaded_leads add column if not exists review_score numeric;\r\nalter table preloaded_leads add column if not exists review_count integer;\r\nalter table preloaded_leads add column if not exists has_website boolean;\r\nalter table preloaded_leads add column if not exists phone_line text not null default '';\r\n";
var _0017_followups_default = "-- Simulated nurture loops started by an email or SMS batch.\r\n-- A click on ?b=slug stops the remaining touches.\r\n\r\ncreate table if not exists outreach_sequences (\r\n  id              text primary key,\r\n  lead_slug       text not null,\r\n  campaign_id     text not null,\r\n  channel         text not null,\r\n  county          text not null default '',\r\n  trade_type      text not null default '',\r\n  strategy        text not null default '',\r\n  status          text not null default 'active',\r\n  stopped_reason  text not null default '',\r\n  created_at      timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists outreach_sequences_slug_idx\r\n  on outreach_sequences (lead_slug, created_at desc);\r\n\r\ncreate unique index if not exists outreach_sequences_active_channel_idx\r\n  on outreach_sequences (lead_slug, channel)\r\n  where status = 'active';\r\n\r\ncreate table if not exists outreach_touches (\r\n  id            text primary key,\r\n  sequence_id   text not null references outreach_sequences(id) on delete cascade,\r\n  step          integer not null,\r\n  label         text not null,\r\n  status        text not null,\r\n  scheduled_at  timestamptz not null,\r\n  body          text not null default '',\r\n  created_at    timestamptz not null default now(),\r\n  unique (sequence_id, step)\r\n);\r\n\r\ncreate index if not exists outreach_touches_sequence_idx\r\n  on outreach_touches (sequence_id, step);\r\n\r\nalter table outreach_sequences enable row level security;\r\nalter table outreach_touches enable row level security;\r\n";
var _0018_outreach_queue_default = "-- Paced outreach chunks. Simulation rows are logged. Live rows send only after credentials pass.\r\n\r\ncreate table if not exists outreach_dispatches (\r\n  id                text primary key,\r\n  campaign_id       text not null,\r\n  channel           text not null,\r\n  mode              text not null default 'simulation',\r\n  chunk_index       integer not null,\r\n  chunk_count       integer not null,\r\n  lead_count        integer not null,\r\n  interval_seconds  integer not null default 45,\r\n  payload           text not null default '[]',\r\n  status            text not null default 'queued',\r\n  scheduled_at      timestamptz not null,\r\n  sent_at           timestamptz,\r\n  detail            text not null default '',\r\n  county            text not null default '',\r\n  created_at        timestamptz not null default now(),\r\n  unique (campaign_id, chunk_index)\r\n);\r\n\r\ncreate index if not exists outreach_dispatches_due_idx\r\n  on outreach_dispatches (status, scheduled_at);\r\n\r\ncreate index if not exists outreach_dispatches_sent_idx\r\n  on outreach_dispatches (sent_at desc);\r\n\r\nalter table outreach_dispatches enable row level security;\r\n";
var _0019_nurture_guard_default = "-- Day 3 and Day 6 are sent by the nurture worker. A visit stops a loop only\r\n-- when it carries that sequence's stop token. Anonymous hits stay unverified.\r\n\r\nalter table outreach_sequences add column if not exists stop_token_hash text not null default '';\r\n\r\nalter table outreach_touches add column if not exists attempts integer not null default 0;\r\n\r\nalter table funnel_visits add column if not exists verified boolean not null default false;\r\nalter table funnel_visits add column if not exists client_key text not null default '';\r\n\r\ncreate index if not exists funnel_visits_client_idx\r\n  on funnel_visits (client_key, created_at desc);\r\n\r\ncreate table if not exists outreach_events (\r\n  id          text primary key,\r\n  county      text not null default '',\r\n  channel     text not null default '',\r\n  summary     text not null default '',\r\n  status      text not null default '',\r\n  created_at  timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists outreach_events_created_idx\r\n  on outreach_events (created_at desc);\r\n\r\nalter table outreach_events enable row level security;\r\n";
var _0020_territory_activation_default = "-- Per-lead production mode, plus the checkout that flips it.\r\n\r\nalter table preloaded_leads add column if not exists account_mode text not null default 'simulation';\r\n\r\ncreate table if not exists territory_checkouts (\r\n  id            text primary key,\r\n  lead_slug     text not null,\r\n  plan_id       text not null,\r\n  amount_cents  integer not null,\r\n  processor     text not null default 'desk',\r\n  status        text not null default 'pending',\r\n  payment_ref   text not null default '',\r\n  created_at    timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists territory_activations (\r\n  id             text primary key,\r\n  lead_slug      text not null,\r\n  business_name  text not null default '',\r\n  county         text not null default '',\r\n  plan_id        text not null,\r\n  plan_name      text not null default '',\r\n  amount_cents   integer not null default 0,\r\n  renewal_cents  integer,\r\n  renews_at      timestamptz,\r\n  payment_ref    text not null default '',\r\n  created_at     timestamptz not null default now()\r\n);\r\n\r\ncreate unique index if not exists territory_activations_lead_idx on territory_activations (lead_slug);\r\ncreate index if not exists territory_activations_created_idx on territory_activations (created_at desc);\r\n\r\nalter table territory_checkouts enable row level security;\r\nalter table territory_activations enable row level security;\r\n";
var _0021_open_trades_default = "-- Open trade categories. Built-in niches keep their id. Any other\r\n-- directory category is stored as its own key plus the label operators typed.\r\n\r\nalter table preloaded_leads add column if not exists trade_label text not null default '';\r\n";
var _0022_appointment_slot_default = "-- One open booking per employee and start time. Cancelled rows stay out of the index\r\n-- so that slot can be booked again. Applied on databases that already ran 0002.\r\n\r\ncreate unique index if not exists appointments_no_double_booking\r\n  on appointments (employee_id, starts_at)\r\n  where status in ('pending', 'confirmed');\r\n";
var _0023_hero_stills_default = "-- Swap placeholder hero files for the uploaded stills and loops.\r\n-- Only rows still pointing at those exact placeholders are updated.\r\n\r\nupdate shops set hero_image_url = '/media/heroes/salon.jpg' where hero_image_url = '/media/heroes/salon.svg';\r\nupdate shops set hero_image_url = '/media/heroes/events.jpg' where hero_image_url = '/media/heroes/events.svg';\r\nupdate shops set hero_image_url = '/media/heroes/hvac.jpg' where hero_image_url = '/media/heroes/hvac.svg';\r\nupdate shops set hero_image_url = '/media/heroes/electrical.jpg' where hero_image_url = '/media/heroes/electrical.svg';\r\n\r\nupdate shops\r\nset hero_video_url = '/media/heroes/guide.mp4'\r\nwhere niche = 'guide' and coalesce(hero_video_url, '') = '';\r\n\r\nupdate shops\r\nset hero_image_url = '', hero_video_url = '/media/heroes/photo.mp4'\r\nwhere niche = 'photo'\r\n  and hero_image_url in ('/media/heroes/photo.svg', '')\r\n  and coalesce(hero_video_url, '') = '';\r\n";
