var _0028_send_windows_default = "-- Smart timing remembers whether a batch trickles on weekday hours\r\n-- or waits for a niche window. Existing rows stay on the weekday window.\r\n\r\nalter table outreach_dispatches add column if not exists timing text not null default 'immediate';\r\nalter table outreach_dispatches add column if not exists profile text not null default 'general';\r\n\r\nalter table outreach_sequences add column if not exists timing text not null default 'immediate';\r\n";
var _0029_security_niche_default = "-- Private security joins the bookable niches.\r\n\r\ndo $$\r\ndeclare r record;\r\nbegin\r\n  for r in\r\n    select conname from pg_constraint\r\n    where conrelid = 'shops'::regclass\r\n      and contype = 'c'\r\n      and pg_get_constraintdef(oid) ilike '%niche%'\r\n  loop\r\n    execute format('alter table shops drop constraint %I', r.conname);\r\n  end loop;\r\nend $$;\r\n\r\nalter table shops add constraint shops_niche_check\r\n  check (niche in (\r\n    'location', 'field', 'studio', 'music', 'contractor', 'fitness', 'tattoo', 'guide',\r\n    'salon', 'beauty', 'wellness', 'lessons', 'photo', 'pets', 'clean', 'practice',\r\n    'counsel', 'events', 'trade', 'security'\r\n  ));\r\n\r\nupdate shops\r\nset hero_video_url = '/media/heroes/tiger-deer.mp4'\r\nwhere niche = 'fitness'\r\n  and coalesce(hero_video_url, '') in ('', '/media/tiger.mp4');\r\n\r\nupdate shops\r\nset hero_video_url = '/media/heroes/welding-trade.mp4'\r\nwhere niche = 'trade'\r\n  and coalesce(hero_video_url, '') = ''\r\n  and hero_image_url in ('/media/heroes/trade.jpg', '/media/heroes/trade.svg');\r\n";
var _0030_storefront_default = "-- Per-shop storefront: theme, neon accent, glow, and section order.\r\n-- Hero films stay on shops.hero_video_url and shop_hero_videos.\r\n-- This is the Postgres schema. Point DATABASE_URL at a Supabase pooler to keep the same tables.\r\n\r\nalter table shops add column if not exists theme_profile text not null default '';\r\nalter table shops add column if not exists neon_accent text not null default '';\r\nalter table shops add column if not exists glow_enabled boolean not null default true;\r\nalter table shops add column if not exists layout_json text not null default '[\"staff\",\"estimate\",\"menu\"]';\r\n\r\nalter table employees add column if not exists availability_json text not null default '';\r\n";
var _0031_niche_hero_films_default = "-- Default hero films for niches that were stills. Custom uploads stay put.\r\n\r\nupdate shops set hero_video_url = '/media/heroes/salon.mp4'\r\nwhere niche = 'salon' and coalesce(hero_video_url, '') = ''\r\n  and hero_image_url in ('/media/heroes/salon.jpg', '/media/heroes/salon.svg');\r\n\r\nupdate shops set hero_video_url = '/media/heroes/wellness.mp4'\r\nwhere niche = 'wellness' and coalesce(hero_video_url, '') = ''\r\n  and hero_image_url in ('/media/heroes/wellness.jpg', '/media/heroes/wellness.svg');\r\n\r\nupdate shops set hero_video_url = '/media/heroes/clean.mp4'\r\nwhere niche = 'clean' and coalesce(hero_video_url, '') = ''\r\n  and hero_image_url in ('/media/heroes/clean.jpg', '/media/heroes/clean.svg');\r\n\r\nupdate shops set hero_video_url = '/media/heroes/counsel.mp4'\r\nwhere niche = 'counsel' and coalesce(hero_video_url, '') = ''\r\n  and hero_image_url in ('/media/heroes/counsel.jpg', '/media/heroes/counsel.svg');\r\n\r\nupdate shops set hero_video_url = '/media/heroes/events.mp4'\r\nwhere niche = 'events' and coalesce(hero_video_url, '') = ''\r\n  and hero_image_url in ('/media/heroes/events.jpg', '/media/heroes/events.svg');\r\n";
var _0032_retail_niche_default = "-- Retail / merchandise joins the bookable niches as a product shelf.\r\n\r\ndo $$\r\ndeclare r record;\r\nbegin\r\n  for r in\r\n    select conname from pg_constraint\r\n    where conrelid = 'shops'::regclass\r\n      and contype = 'c'\r\n      and pg_get_constraintdef(oid) ilike '%niche%'\r\n  loop\r\n    execute format('alter table shops drop constraint %I', r.conname);\r\n  end loop;\r\nend $$;\r\n\r\nalter table shops add constraint shops_niche_check\r\n  check (niche in (\r\n    'location', 'field', 'studio', 'music', 'contractor', 'fitness', 'tattoo', 'guide',\r\n    'salon', 'beauty', 'wellness', 'lessons', 'photo', 'pets', 'clean', 'practice',\r\n    'counsel', 'events', 'trade', 'security', 'retail'\r\n  ));\r\n";
var _0033_lead_audits_default = "-- Customer audit reports from the public estimate. The photo never leaves the device.\r\n\r\ncreate table if not exists lead_audits (\r\n  id             text primary key,\r\n  lead_slug      text not null default '',\r\n  shop_id        text references shops(id) on delete set null,\r\n  customer_name  text not null,\r\n  channel        text not null,\r\n  contact        text not null,\r\n  lane           text not null,\r\n  low_cents      integer not null,\r\n  high_cents     integer not null,\r\n  impact         integer not null,\r\n  summary        text not null,\r\n  delivered      boolean not null default false,\r\n  created_at     timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists lead_audits_lead_idx on lead_audits (lead_slug, created_at desc);\r\ncreate index if not exists lead_audits_shop_idx on lead_audits (shop_id, created_at desc);\r\n\r\nalter table lead_audits enable row level security;\r\n";
var _0034_audit_status_default = "-- An estimate can be confirmed back to the customer who requested it.\r\n\r\nalter table lead_audits add column if not exists status text not null default 'open';\r\n";
var _0035_funnel_source_default = "-- Desk-built outreach links, separate from the regional roster.\r\n\r\nalter table preloaded_leads add column if not exists source text not null default '';\r\n\r\ncreate index if not exists preloaded_leads_source_idx on preloaded_leads (source, created_at desc);\r\n";
